import React, { useState, useEffect } from 'react';
import { Navigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import {
  BookOpen,
  Plus,
  Calendar,
  Clock,
  AlertCircle,
  Edit2,
  Trash2,
  Filter,
  Search,
  X,
  Check,
  Award,
  TrendingUp
} from 'lucide-react';

interface AssignmentFormData {
  title: string;
  subject: string;
  description: string;
  dueDate: string;
  dueTime: string;
  grade?: number;
}

const Assignments: React.FC = () => {
  const { user, assignments, addAssignment, updateAssignment, deleteAssignment, darkMode } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAssignment, setEditingAssignment] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'pending' | 'in-progress' | 'completed'>('all');
  const [filterSubject, setFilterSubject] = useState<string>('all');
  const [formData, setFormData] = useState<AssignmentFormData>({
    title: '',
    subject: '',
    description: '',
    dueDate: '',
    dueTime: '',
    grade: undefined
  });

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  // Get unique subjects for filter
  const subjects = Array.from(new Set(assignments.map(a => a.subject)));

  // Filter and search assignments
  const filteredAssignments = assignments.filter(assignment => {
    const matchesSearch = assignment.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      assignment.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (assignment.description && assignment.description.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = filterStatus === 'all' || assignment.status === filterStatus;
    const matchesSubject = filterSubject === 'all' || assignment.subject === filterSubject;
    return matchesSearch && matchesStatus && matchesSubject;
  }).sort((a, b) => {
    // Sort by due date, then by status
    const dateA = new Date(a.dueDate).getTime();
    const dateB = new Date(b.dueDate).getTime();
    if (dateA !== dateB) return dateA - dateB;

    const statusOrder = { pending: 0, 'in-progress': 1, completed: 2 };
    return statusOrder[a.status] - statusOrder[b.status];
  });

  const resetForm = () => {
    setFormData({
      title: '',
      subject: '',
      description: '',
      dueDate: '',
      dueTime: '',
      grade: undefined
    });
    setEditingAssignment(null);
  };

  const openModal = (assignment?: any) => {
    if (assignment) {
      setEditingAssignment(assignment.id);
      const dueDate = new Date(assignment.dueDate);
      setFormData({
        title: assignment.title,
        subject: assignment.subject,
        description: assignment.description || '',
        dueDate: dueDate.toISOString().split('T')[0],
        dueTime: dueDate.toTimeString().slice(0, 5),
        grade: assignment.grade
      });
    } else {
      resetForm();
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    resetForm();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim() || !formData.subject.trim()) return;

    const dueDateTime = formData.dueDate && formData.dueTime
      ? new Date(`${formData.dueDate}T${formData.dueTime}`)
      : new Date();

    const assignmentData = {
      title: formData.title.trim(),
      subject: formData.subject.trim(),
      description: formData.description.trim(),
      dueDate: dueDateTime.toISOString(),
      status: 'pending' as const,
      grade: formData.grade
    };

    if (editingAssignment) {
      updateAssignment(editingAssignment, assignmentData);
    } else {
      addAssignment(assignmentData);
    }

    closeModal();
  };

  const updateAssignmentStatus = (assignmentId: string, status: 'pending' | 'in-progress' | 'completed') => {
    updateAssignment(assignmentId, { status });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-100 text-green-800 border-green-200 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800';
      case 'in-progress': return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800';
      case 'pending': return 'bg-yellow-100 text-yellow-800 border-yellow-200 dark:bg-yellow-900/30 dark:text-yellow-300 dark:border-yellow-800';
      default: return 'bg-gray-100 text-gray-800 border-gray-200 dark:bg-gray-900/30 dark:text-gray-300 dark:border-gray-700';
    }
  };

  const getGradeColor = (grade?: number) => {
    if (!grade) return 'text-gray-500';
    if (grade >= 90) return 'text-green-600 font-semibold';
    if (grade >= 80) return 'text-blue-600 font-semibold';
    if (grade >= 70) return 'text-yellow-600 font-semibold';
    return 'text-red-600 font-semibold';
  };

  const getDaysLeft = (dueDate: string) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const diff = Math.ceil((due.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    return diff;
  };

  const getDaysLeftColor = (daysLeft: number) => {
    if (daysLeft < 0) return 'text-red-600 font-semibold';
    if (daysLeft === 0) return 'text-orange-600 font-semibold';
    if (daysLeft === 1) return 'text-yellow-600';
    return 'text-gray-600';
  };

  const formatDueDate = (dueDate: string) => {
    const date = new Date(dueDate);
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    if (date.toDateString() === today.toDateString()) {
      return `Today at ${date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    } else if (date.toDateString() === tomorrow.toDateString()) {
      return `Tomorrow at ${date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    } else {
      return date.toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' }) +
        ` at ${date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    }
  };

  // Calculate statistics
  const stats = {
    total: assignments.length,
    pending: assignments.filter(a => a.status === 'pending').length,
    inProgress: assignments.filter(a => a.status === 'in-progress').length,
    completed: assignments.filter(a => a.status === 'completed').length,
    overdue: assignments.filter(a => a.status !== 'completed' && new Date(a.dueDate) < new Date()).length,
    averageGrade: assignments.filter(a => a.grade !== undefined).length > 0
      ? Math.round(assignments.filter(a => a.grade !== undefined).reduce((sum, a) => sum + (a.grade || 0), 0) / assignments.filter(a => a.grade !== undefined).length)
      : null
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Assignment Tracker
          </h1>
          <p className="text-gray-600 dark:text-gray-300 mt-2">
            Track your assignments and deadlines
          </p>
        </div>
        <button
          onClick={() => openModal()}
          className="btn-primary"
        >
          <Plus className="w-4 h-4 mr-2" />
          Add Assignment
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Total</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.total}</p>
            </div>
            <BookOpen className="w-8 h-8 text-blue-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Pending</p>
              <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
            </div>
            <Clock className="w-8 h-8 text-yellow-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">In Progress</p>
              <p className="text-2xl font-bold text-blue-600">{stats.inProgress}</p>
            </div>
            <TrendingUp className="w-8 h-8 text-blue-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Completed</p>
              <p className="text-2xl font-bold text-green-600">{stats.completed}</p>
            </div>
            <Check className="w-8 h-8 text-green-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Overdue</p>
              <p className="text-2xl font-bold text-red-600">{stats.overdue}</p>
            </div>
            <AlertCircle className="w-8 h-8 text-red-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Avg Grade</p>
              <p className={`text-2xl font-bold ${getGradeColor(stats.averageGrade || 0)}`}>
                {stats.averageGrade || '--'}
              </p>
            </div>
            <Award className="w-8 h-8 text-purple-500" />
          </div>
        </div>
      </div>

      {/* Filters and Search */}
      <div className="card p-4">
        <div className="flex flex-col lg:flex-row gap-4">
          {/* Search */}
          <div className="flex-1">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search assignments..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input pl-10 w-full"
              />
            </div>
          </div>

          {/* Filters */}
          <div className="flex gap-2">
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
              className="input"
            >
              <option value="all">All Status</option>
              <option value="pending">Pending</option>
              <option value="in-progress">In Progress</option>
              <option value="completed">Completed</option>
            </select>

            <select
              value={filterSubject}
              onChange={(e) => setFilterSubject(e.target.value)}
              className="input"
            >
              <option value="all">All Subjects</option>
              {subjects.map(subject => (
                <option key={subject} value={subject}>{subject}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Assignments List */}
      <div className="space-y-3">
        {filteredAssignments.length === 0 ? (
          <div className="card p-8 text-center">
            <BookOpen className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
              {searchTerm || filterStatus !== 'all' || filterSubject !== 'all'
                ? 'No assignments found'
                : 'No assignments yet'}
            </h3>
            <p className="text-gray-600 dark:text-gray-300 mb-4">
              {searchTerm || filterStatus !== 'all' || filterSubject !== 'all'
                ? 'Try adjusting your filters or search terms'
                : 'Create your first assignment to get started'}
            </p>
            {!searchTerm && filterStatus === 'all' && filterSubject === 'all' && (
              <button
                onClick={() => openModal()}
                className="btn-primary"
              >
                <Plus className="w-4 h-4 mr-2" />
                Add Your First Assignment
              </button>
            )}
          </div>
        ) : (
          filteredAssignments.map(assignment => {
            const daysLeft = getDaysLeft(assignment.dueDate);
            const isOverdue = daysLeft < 0 && assignment.status !== 'completed';

            return (
              <div
                key={assignment.id}
                className={`card p-4 transition-all hover:shadow-md ${assignment.status === 'completed' ? 'opacity-75' : ''
                  } ${isOverdue ? 'border-red-200 dark:border-red-800' : ''}`}
              >
                <div className="flex items-start gap-4">
                  {/* Status Icon */}
                  <div className="mt-1">
                    {assignment.status === 'completed' ? (
                      <div className="w-5 h-5 rounded-full bg-green-500 flex items-center justify-center">
                        <Check className="w-3 h-3 text-white" />
                      </div>
                    ) : assignment.status === 'in-progress' ? (
                      <div className="w-5 h-5 rounded-full bg-blue-500 flex items-center justify-center">
                        <TrendingUp className="w-3 h-3 text-white" />
                      </div>
                    ) : (
                      <div className="w-5 h-5 rounded-full border-2 border-yellow-500"></div>
                    )}
                  </div>

                  {/* Assignment Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className={`font-medium text-gray-900 dark:text-white ${assignment.status === 'completed' ? 'line-through' : ''
                            }`}>
                            {assignment.title}
                          </h3>
                          {assignment.grade !== undefined && (
                            <span className={`text-sm font-medium ${getGradeColor(assignment.grade)}`}>
                              {assignment.grade}%
                            </span>
                          )}
                        </div>

                        <div className="flex items-center gap-3 mb-2">
                          <span className="text-sm font-medium text-blue-600 dark:text-blue-400">
                            {assignment.subject}
                          </span>
                          <span className={`text-xs px-2 py-1 rounded-full border ${getStatusColor(assignment.status)}`}>
                            {assignment.status.replace('-', ' ')}
                          </span>
                        </div>

                        {assignment.description && (
                          <p className="text-sm text-gray-600 dark:text-gray-300 mb-2">
                            {assignment.description}
                          </p>
                        )}

                        <div className="flex items-center gap-3">
                          <div className="flex items-center text-xs text-gray-500 dark:text-gray-400">
                            <Calendar className="w-3 h-3 mr-1" />
                            <span className={getDaysLeftColor(daysLeft)}>
                              {daysLeft === 0 ? 'Due today' :
                                daysLeft === 1 ? 'Due tomorrow' :
                                  daysLeft === -1 ? 'Overdue yesterday' :
                                    daysLeft < -1 ? `Overdue ${Math.abs(daysLeft)} days ago` :
                                      daysLeft > 0 ? `Due in ${daysLeft} days` : 'Due today'}
                            </span>
                          </div>
                          <div className="flex items-center text-xs text-gray-500 dark:text-gray-400">
                            <Clock className="w-3 h-3 mr-1" />
                            {formatDueDate(assignment.dueDate)}
                          </div>
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-2">
                        {/* Status Update Buttons */}
                        {assignment.status !== 'completed' && (
                          <div className="flex gap-1">
                            {assignment.status === 'pending' && (
                              <button
                                onClick={() => updateAssignmentStatus(assignment.id, 'in-progress')}
                                className="p-2 text-blue-500 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300"
                                title="Mark as in progress"
                              >
                                <TrendingUp className="w-4 h-4" />
                              </button>
                            )}
                            <button
                              onClick={() => updateAssignmentStatus(assignment.id, 'completed')}
                              className="p-2 text-green-500 hover:text-green-700 dark:text-green-400 dark:hover:text-green-300"
                              title="Mark as completed"
                            >
                              <Check className="w-4 h-4" />
                            </button>
                          </div>
                        )}

                        <button
                          onClick={() => openModal(assignment)}
                          className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
                          aria-label="Edit assignment"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => deleteAssignment(assignment.id)}
                          className="p-2 text-red-500 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300"
                          aria-label="Delete assignment"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Add/Edit Assignment Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="card w-full max-w-md">
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                {editingAssignment ? 'Edit Assignment' : 'Add New Assignment'}
              </h2>
              <button
                onClick={closeModal}
                className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              {/* Title */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Title *
                </label>
                <input
                  type="text"
                  required
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  className="input w-full"
                  placeholder="Enter assignment title"
                />
              </div>

              {/* Subject */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Subject *
                </label>
                <input
                  type="text"
                  required
                  value={formData.subject}
                  onChange={(e) => setFormData({ ...formData, subject: e.target.value })}
                  className="input w-full"
                  placeholder="Enter subject name"
                />
              </div>

              {/* Description */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Description
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="input w-full resize-none"
                  rows={3}
                  placeholder="Add assignment description (optional)"
                />
              </div>

              {/* Due Date */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    Due Date
                  </label>
                  <input
                    type="date"
                    value={formData.dueDate}
                    onChange={(e) => setFormData({ ...formData, dueDate: e.target.value })}
                    className="input w-full"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    Due Time
                  </label>
                  <input
                    type="time"
                    value={formData.dueTime}
                    onChange={(e) => setFormData({ ...formData, dueTime: e.target.value })}
                    className="input w-full"
                  />
                </div>
              </div>

              {/* Grade (for completed assignments) */}
              {editingAssignment && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    Grade (0-100)
                  </label>
                  <input
                    type="number"
                    min="0"
                    max="100"
                    value={formData.grade || ''}
                    onChange={(e) => setFormData({ ...formData, grade: e.target.value ? parseInt(e.target.value) : undefined })}
                    className="input w-full"
                    placeholder="Enter grade if completed"
                  />
                </div>
              )}

              {/* Actions */}
              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={closeModal}
                  className="btn-secondary flex-1"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn-primary flex-1"
                >
                  {editingAssignment ? 'Update Assignment' : 'Add Assignment'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Assignments;
